package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class RoundedSharingStoryTest {
 @Test public void allConditionsRoundOnceUsingIndependentIntegerArithmetic(){assertEquals(440000,RoundedSharingStory.domainSize());Checker checker=new Checker();for(int i=0;i<440000;i++){Question q=RoundedSharingStory.at(i);var v=RoundedSharingStory.read(q);assertNotNull(v);int cents=v.total().movePointRight(2).intValueExact();long numerator=cents*(v.places()==2?1:1),denominator=v.divisor()*(v.places()==1?10:1);long whole=numerator/denominator,remainder=numerator%denominator;BigDecimal expected=BigDecimal.valueOf(whole+(2*remainder>=denominator?1:0),v.places());assertEquals(0,expected.compareTo(new BigDecimal(q.answers[0])));assertTrue(checker.check(q,List.of(),List.of(expected.toPlainString())).correct());}}
 @Test public void nonterminatingGuardAndCarryUseTenBlankPublicSteps(){for(int p:List.of(1,2))for(int cents:List.of(0,100,1999,9999)){Question q=RoundedSharingStory.make(cents,3,p,"L");q.expression="poison";q.answers=new String[]{"999"};var v=RoundedSharingStory.read(q);BigDecimal guard=v.total().divide(BigDecimal.valueOf(3),p+1,RoundingMode.DOWN),unit=BigDecimal.ONE.movePointLeft(p),base=guard.divideToIntegralValue(unit).multiply(unit);int digit=guard.subtract(base).movePointRight(p+1).intValue();List<String> values=List.of(v.total().toPlainString(),"3",""+p,guard.toPlainString(),unit.toPlainString(),""+digit,digit>=5?"raise":"keep",base.toPlainString(),digit>=5?unit.toPlainString():"0",v.total().divide(BigDecimal.valueOf(3),p,RoundingMode.HALF_UP).toPlainString());HelpPlan h=HelpPlan.forQuestion(q);assertEquals(10,h.size());assertFalse(h.canTransfer());for(int j=0;j<10;j++){assertTrue("stage"+j,h.step(j).accepts(values.get(j)));assertEquals("",h.step(j).after);}assertFalse(h.step(3).accepts(guard.add(unit).toPlainString()));}}
 @Test public void gradeLinkFreshnessAndFallbackScope(){var pack=GlobalCurriculum.packs("GB").stream().filter(x->x.id.equals("england-primary-2021-v1")).findFirst().orElseThrow();assertTrue(pack.inGrade(RoundedSharingStory.ID,6));Generator g=new Generator(new Random(97));List<String> recent=new ArrayList<>();for(int i=0;i<150;i++){Question q=g.next(RoundedSharingStory.ID,recent,false,GlobalCurriculum.limits(pack.id,RoundedSharingStory.ID,6));assertFalse(recent.contains(q.signature()));recent.add(q.signature());}Learning.Profile profile=new Learning.Profile();profile.countryCode="KR";profile.educationSystem="kr-national";assertTrue(GlobalCurriculum.available(profile).stream().noneMatch(s->RoundedSharingStory.supports(s.id)));}
}
